function fixFile(problems) {
  if (problems.length === 0) return;
  const filePath = problems[0].path;
  let content = fs.readFileSync(filePath, 'utf8');
  let lines = content.split('\n');

  problems.forEach(p => {
    const match = p.message.match(/The class \`([^\`]+)\` can be written as \`([^\`]+)\`/);
    if (match) {
      const oldClass = match[1];
      const newClass = match[2];
      const lineIdx = p.startLine - 1;
      
      lines[lineIdx] = lines[lineIdx].replace(oldClass, newClass);
    }
  });

  fs.writeFileSync(filePath, lines.join('\n'), 'utf8');
  console.log('Fixed', filePath);
}

try {
  fixFile(pageProblems);
  fixFile(modalProblems);
} catch (err) {
  console.error(err);
}
